const ctx = $items('Video Gate')[0]?.json;

if (!ctx) {
  throw new Error('VIDEO_CONTEXT_NOT_FOUND');
}

const raw = $json?.message?.content;

if (!raw) {
  throw new Error('OLLAMA_EMPTY_RESPONSE');
}

let plan;

try {
  plan = JSON.parse(raw);
} catch {
  throw new Error('OLLAMA_INVALID_JSON: ' + raw);
}

const script = String(plan.script || '').trim();

const terms = Array.isArray(plan.search_terms)
  ? plan.search_terms.map(x => String(x).trim()).filter(Boolean)
  : [];

if (!script) {
  throw new Error('SCRIPT_EMPTY');
}

if (terms.length < 1) {
  throw new Error('SEARCH_TERMS_EMPTY');
}

return [{
  json:{
    ...ctx,
    video_script:script,
    video_terms:terms
  }
}];

const ctxItems = $items('Status Gate');

if (!ctxItems.length) {
  throw new Error('STATUS_CONTEXT_NOT_FOUND');
}

const ctx = ctxItems[0].json;

const payload = $json?.data;

if (!payload) {
  throw new Error(
    'INVALID_STATUS_RESPONSE: ' +
    JSON.stringify($json)
  );
}

const store = $getWorkflowStaticData('global');

if (!store.jobs) {
  store.jobs = [];
}

const index = store.jobs.findIndex(
  j =>
    String(j.telegram_id) === String(ctx.telegram_id) &&
    j.task_id === ctx.task_id
);

let status = 'processing';

if (
  payload.state === -1 ||
  payload.failed_stage ||
  payload.error
) {
  status = 'failed';
} else if (
  Number(payload.progress || 0) >= 100
) {
  status = 'completed';
}

if (index >= 0) {
  store.jobs[index] = {
    ...store.jobs[index],
    status,
    state: payload.state,
    progress: Number(payload.progress || 0),
    failed_stage: payload.failed_stage ?? null,
    error: payload.error ?? null,
    videos: payload.videos ?? null,
    combined_videos: payload.combined_videos ?? null,
    audio_file: payload.audio_file ?? null,
    updated_at: new Date().toISOString()
  };
}

let message =
`📊 حالة الفيديو

🎬 الموضوع:
${index >= 0 ? store.jobs[index].topic : ''}

🆔 Task ID:
${ctx.task_id}

📈 التقدم:
${payload.progress ?? 0}%

⚙️ الحالة:
${status}`;

if (payload.failed_stage) {
  message += `

❌ مرحلة الفشل:
${payload.failed_stage}`;
}

if (payload.error) {
  message += `

⚠️ الخطأ:
${payload.error}`;
}

if (status === 'completed') {
  message += `

✅ الفيديو مكتمل`;
}

return [{
  json:{
    chat_id:ctx.chat_id,
    telegram_id:ctx.telegram_id,
    task_id:ctx.task_id,
    real_status:status,
    progress:Number(payload.progress || 0),
    state:payload.state,
    status_reply:message
  }
}];
